-- Mirrors already-applied live migration 20260826024647.
-- Repository synchronization only. Do not apply this migration to the current live sandbox.
-- Mapping proposals are not identity claims and do not enable Graph consumption.

CREATE TABLE public.timeline_v2_graph_identity_candidates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  timeline_candidate_id uuid NOT NULL REFERENCES public.timeline_placement_candidates(id),
  timeline_event_id uuid NOT NULL REFERENCES public.events(id),
  graph_node_id uuid NOT NULL REFERENCES public.nodes(id),
  proposal_method text NOT NULL,
  candidate_revision_timestamp timestamptz NOT NULL,
  graph_node_revision_timestamp timestamptz NOT NULL,
  proposal_fingerprint text NOT NULL,
  proposal_fingerprint_hash text NOT NULL UNIQUE,
  proposal_basis jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT timeline_v2_graph_identity_candidates_proposal_method_check
    CHECK (proposal_method = ANY (ARRAY[
      'arc_root_existing_node_candidate',
      'same_arc_existing_node_candidate',
      'explicit_provenance_candidate',
      'owner_direct_candidate'
    ])),
  CONSTRAINT timeline_v2_graph_identity_candidates_proposal_basis_check
    CHECK (jsonb_typeof(proposal_basis) = 'object'),
  CONSTRAINT timeline_v2_graph_identity_cand_proposal_fingerprint_hash_check
    CHECK (proposal_fingerprint_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT timeline_v2_graph_identity_ca_timeline_candidate_id_graph_n_key
    UNIQUE (timeline_candidate_id, graph_node_id, candidate_revision_timestamp, graph_node_revision_timestamp, proposal_method),
  CONSTRAINT timeline_v2_graph_identity_ca_id_timeline_candidate_id_grap_key
    UNIQUE (id, timeline_candidate_id, graph_node_id)
);

CREATE TABLE public.timeline_v2_graph_identity_audits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  mapping_candidate_id uuid NOT NULL,
  timeline_candidate_id uuid NOT NULL,
  graph_node_id uuid NOT NULL,
  audit_outcome text NOT NULL,
  independent_provenance text NOT NULL,
  audit_method_version text NOT NULL,
  structured_judgment jsonb NOT NULL DEFAULT '{}'::jsonb,
  notes text NULL,
  audited_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT timeline_v2_graph_identity_audits_mapping_candidate_id_key UNIQUE (mapping_candidate_id),
  CONSTRAINT timeline_v2_graph_identity_audits_audit_outcome_check
    CHECK (audit_outcome = ANY (ARRAY['confirmed_same_event', 'rejected_not_same_event', 'undetermined'])),
  CONSTRAINT timeline_v2_graph_identity_audits_structured_judgment_check
    CHECK (jsonb_typeof(structured_judgment) = 'object'),
  CONSTRAINT timeline_v2_graph_identity_audits_exact_mapping_binding
    FOREIGN KEY (mapping_candidate_id, timeline_candidate_id, graph_node_id)
    REFERENCES public.timeline_v2_graph_identity_candidates(id, timeline_candidate_id, graph_node_id)
);

CREATE OR REPLACE FUNCTION public.validate_timeline_v2_graph_identity_candidate()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  tc public.timeline_placement_candidates%rowtype;
  gn public.nodes%rowtype;
  sa public.story_arcs%rowtype;
BEGIN
  SELECT * INTO tc FROM public.timeline_placement_candidates WHERE id = NEW.timeline_candidate_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown Timeline candidate %', NEW.timeline_candidate_id USING ERRCODE = '23503';
  END IF;

  IF tc.event_id <> NEW.timeline_event_id THEN
    RAISE EXCEPTION 'timeline_event_id does not match Timeline candidate event_id' USING ERRCODE = '23514';
  END IF;

  IF tc.candidate_updated_at <> NEW.candidate_revision_timestamp THEN
    RAISE EXCEPTION 'candidate revision timestamp is stale or mismatched' USING ERRCODE = '23514';
  END IF;

  IF tc.state IN ('rejected','invalidated') THEN
    RAISE EXCEPTION 'rejected or invalidated Timeline candidates cannot receive new Graph identity proposals' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO gn FROM public.nodes WHERE id = NEW.graph_node_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'unknown Graph node %', NEW.graph_node_id USING ERRCODE = '23503';
  END IF;

  IF gn.updated_at <> NEW.graph_node_revision_timestamp THEN
    RAISE EXCEPTION 'Graph node revision timestamp is stale or mismatched' USING ERRCODE = '23514';
  END IF;

  IF NEW.proposal_method = 'arc_root_existing_node_candidate' THEN
    SELECT * INTO sa FROM public.story_arcs WHERE id = tc.arc_id;
    IF NOT FOUND OR sa.root_node_id IS DISTINCT FROM NEW.graph_node_id THEN
      RAISE EXCEPTION 'arc-root proposal must target the candidate Arc root node' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.proposal_method = 'same_arc_existing_node_candidate' THEN
    IF gn.arc_id IS DISTINCT FROM tc.arc_id THEN
      RAISE EXCEPTION 'same-Arc proposal must target a node in the candidate Arc' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE TRIGGER timeline_v2_graph_identity_candidates_validate
  BEFORE INSERT ON public.timeline_v2_graph_identity_candidates
  FOR EACH ROW EXECUTE FUNCTION public.validate_timeline_v2_graph_identity_candidate();

CREATE TRIGGER timeline_v2_graph_identity_candidates_block_mutation
  BEFORE DELETE OR UPDATE ON public.timeline_v2_graph_identity_candidates
  FOR EACH ROW EXECUTE FUNCTION public.timeline_placement_block_immutable_mutation();

CREATE TRIGGER timeline_v2_graph_identity_audits_block_mutation
  BEFORE DELETE OR UPDATE ON public.timeline_v2_graph_identity_audits
  FOR EACH ROW EXECUTE FUNCTION public.timeline_placement_block_immutable_mutation();

ALTER TABLE public.timeline_v2_graph_identity_candidates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.timeline_v2_graph_identity_audits ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.timeline_v2_graph_identity_candidates FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.timeline_v2_graph_identity_audits FROM PUBLIC, anon, authenticated;

